def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    owner = [[-1] * w for _ in range(h)]
    components = []

    # Find each non-background object using 4-way connectivity.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or owner[r][c] != -1:
                continue
            idx = len(components)
            color = grid[r][c]
            stack = [(r, c)]
            owner[r][c] = idx
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            owner[ny][nx] == -1 and grid[ny][nx] == color):
                        owner[ny][nx] = idx
                        stack.append((ny, nx))
            components.append((color, cells))

    # Objects in the sequence can touch diagonally.
    edges = [set() for _ in components]
    for r in range(h):
        for c in range(w):
            a = owner[r][c]
            if a < 0:
                continue
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        b = owner[nr][nc]
                        if b >= 0 and b != a:
                            edges[a].add(b)

    endpoints = [i for i, e in enumerate(edges) if len(e) <= 1]
    start = min(
        endpoints or range(len(components)),
        key=lambda i: min(components[i][1])
    )

    order = []
    prev, cur = -1, start
    while cur not in order:
        order.append(cur)
        nxt = sorted(i for i in edges[cur] if i != prev and i not in order)
        if not nxt:
            break
        prev, cur = cur, nxt[0]

    return [[components[i][0]] for i in order
