                                for xx in range(x, W, pw)]
                        counts = {}
                        for v in vals:
                            counts[v] = counts.get(v, 0) + 1
                        value = max(counts, key=counts.get)
                        tr.append(value)
                        errors += len(vals) - counts[value]
                    tile.append(tr)
                score = errors + 0.05 * ph * pw
                if best is None or score < best[0]:
                    best = (score, tile, ph, pw)

        _, tile, ph, pw = best
        for y in range(H):
            for x in range(W):
                g[r0 + y][c0 + x] = tile[y % ph][x % pw]

