            minc = min(x for y, x, v in cells)
            maxc = max(x for y, x, v in cells)
            frame = grid[minr][minc]
            objects.append({
                "cells": cells,
                "r": minr, "c": minc,
                "left": minc, "right": maxc,
                "frame": frame
            })

    # Pack frame-8 objects to the left, and frame-2 objects to the right.
