def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 7
    ref = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not ref:
        return [row[:] for row in grid]

    rs = [r for r, c in ref]
    cs = [c for r, c in ref]
    if len(set(rs)) == 1:
        orient = "h"
        intercept = lambda r, c: r
    elif len(set(cs)) == 1:
        orient = "v"
        intercept = lambda r, c: c
    elif all(r + c == ref[0][0] + ref[0][1] for r, c in ref):
        orient = "neg"
        intercept = lambda r, c: r + c
    else:
        orient = "pos"
        intercept = lambda r, c: r - c

    ref_intercept = intercept(*ref[0])
    out = [[bg] * w for _ in range(h)]

    # Keep the reference line in place.
    for r, c in ref:
        out[r][c] = 8

    colors = set(grid[r][c] for r in range(h) for c in range(w)) - {bg, 8}
    for color in colors:
        offsets = {intercept(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == color}
        for target in offsets:
            delta = target - ref_intercept
            if orient == "h":
                dr, dc = delta, 0
            elif orient == "v":
                dr, dc = 0, delta
            elif orient == "neg":
                if delta % 2:
                    continue
                dr = dc = delta // 2
            else:
                if delta % 2:
                    continue
                dr, dc = delta // 2, -delta // 2

            for r, c in ref:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    bg = max(counts, key=counts.get)

    occupied = {
        (r, c): grid[r][c]
        for r in range(h) for c in range(w)
        if grid[r][c] != bg
    }
    if not occupied:
        return [row[:] for row in grid]

    directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
    dr, dc = max(
        directions,
        key=lambda d: sum(
            (r + d[0], c + d[1]) in occupied for r, c in occupied
        )
    )

    stripes = {}
    for (r, c), color in occupied.items():
        if (dr, dc) == (0, 1):
            key, t = r, c
        elif (dr, dc) == (1, 0):
            key, t = c, r
        elif (dr, dc) == (1, 1):
            key, t = r - c, r
        else:
            key, t = r + c, r
        stripes.setdefault(key, {})[t] = color

    def runs_for(line):
        ts = sorted(line)
        runs = []
        run = [ts[0]]
        for t in ts[1:]:
            if t == run[-1] + 1:
                run.append(t)
            else:
                runs.append(run)
                run = [t]
        runs.append(run)
        return runs

    keys = sorted(stripes)
    anchor_runs = runs_for(stripes[keys[len(keys) // 2]])
    target_len = max(map(len, anchor_runs))

    # Extend/truncate toward the side most commonly shared by the segments.
    starts, ends = {}, {}
    for line in stripes.values():
        for run in runs_for(line):
            starts[run[0]] = starts.get(run[0], 0) + 1
            ends[run[-1]] = ends.get(run[-1], 0) + 1
    start_score = max(starts.values())
    end_score = max(ends.values())
    align_start = start_score > end_score

    out = [[bg] * w for _ in range(h)]
    for key, line in stripes.items():
        for run in runs_for(line):
            color = line[run[0]]
            if align_start:
                ts = range(run[0], run[0] + target_len)
            else:
                ts = range(run[-1] - target_len + 1, run[-1] + 1)

            for t in ts:
                if (dr, dc) == (0, 1):
                    r, c = key, t
                elif (dr, dc) == (1, 0):
                    r, c = t, key
                elif (dr, dc) == (1, 1):
                    r, c = t, t - key
