                i = min(near, key=lambda j: min(
                    abs(r-y) + abs(c-x) for y, x in objs[j]["cells"]))
                objs[i]["ports"].append((r, c))

    if not objs:
        return [row[:] for row in grid]

    # The central object (color 4) stays at its original position.
    anchor = next((i for i, o in enumerate(objs) if o["color"] == 4), 0)
    initial = [(anchor, 0, 0)]
    remaining = frozenset(i for i in range(len(objs)) if i != anchor)

    def state_geometry(state):
        occupied, ports = set(), set()
        for i, dr, dc in state:
            o = objs[i]
            occupied.update((r + dr, c + dc) for r, c in o["cells"])
            ports.update((r + dr, c + dc) for r, c in o["ports"])
        return occupied, ports

    # Grow assemblies by aligning marker cells exactly. Keep several alternatives
    # because a piece may have multiple possible matching markers.
    beam = [(initial, remaining)]
    for _ in range(len(remaining)):
        candidates = []
        for state, rem in beam:
            occupied, ports = state_geometry(state)
            for i in rem:
                o = objs[i]
                for pr, pc in o["ports"]:
                    for qr, qc in ports:
                        dr, dc = qr - pr, qc - pc
                        moved = {(r + dr, c + dc) for r, c in o["cells"]}
                        if moved & occupied:
                            continue
                        newstate = state + [(i, dr, dc)]
                        newrem = rem - {i}
                        allcells, allports = state_geometry(newstate)
                        points = allcells | allports
                        if points:
                            minr = min(r for r, c in points)
                            maxr = max(r for r, c in points)
                            minc = min(c for r, c in points)
                            maxc = max(c for r, c in points)
                            area = (maxr - minr + 1) * (maxc - minc + 1)
                        else:
                            area = 0
                        # Prefer compact placements and alignments that join
                        # several markers simultaneously.
                        matched = len({(r + dr, c + dc) for r, c in o["ports"]} & ports)
                        score = area - 5 * matched
                        candidates.append((score, newstate, newrem))

        if not candidates:
            # Keep any unconnected pieces in their input positions.
            state, rem = beam[0]
            for i in rem:
                state = state + [(i, 0, 0)]
            beam = [(state, frozenset())]
            break
        candidates.sort(key=lambda x: x[0])
        beam = [(s, r) for _, s, r in candidates[:250]]

    state = beam[0][0]
    out = [[0] * w for _ in range(h)]
    for i, dr, dc in state:
        o = objs[i]
        for r, c in o["cells"]:
            y, x = r + dr, c + dc
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = o["color"]
    for i, dr, dc in state:
        for r, c in objs[i]["ports"]:
            y, x = r + dr, c + dc
            if 0 <= y < h and 0 <= x < w and out[y][x] == 0:
                out[y][x] = 2
    return out

def transform(grid):
    g = [row[:] for row in grid]
