    # The three colors shown around the 3-marker in the upper-left corner.
    key = {g[r][c] for r in range(min(3, h)) for c in range(min(3, w))
           if g[r][c] not in (0, 3, 7)}

    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 7 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            comp = []
            colors = set()
            has_marker = False
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                if g[x][y] == 3:
                    has_marker = True
                elif g[x][y] != 0:
                    colors.add(g[x][y])
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and g[nx][ny] != 7 and not seen[nx][ny]:
                        seen[nx][ny] = True
                        stack.append((nx, ny))
            if key and key <= colors and not has_marker:
                for x, y in comp:
                    if g[x][y] != 7:
                        g[x][y] = 0
    return g

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    proposals = {}

    # Find connected components of color 1.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 1 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)

            # Extend a colored band outward from one side of this component.
            def extend_vertical(start_row, step, lo, hi):
                if not (0 <= start_row < h):
                    return
                runs = []
                c = lo
                while c <= hi:
                    if grid[start_row][c] not in (1, 8):
                        a = c
                        while c + 1 <= hi and grid[start_row][c + 1] not in (1, 8):
                            c += 1
                        runs.append((a, c))
                    c += 1

                for a, b in runs:
                    layers = [[grid[start_row][x] for x in range(a, b + 1)]]
                    nr = start_row + step
                    if 0 <= nr < h and all(grid[nr][x] not in (1, 8) for x in range(a, b + 1)):
                        layers.append([grid[nr][x] for x in range(a, b + 1)])
                    d = 0
                    rr = start_row
                    while 0 <= rr < h:
                        vals = layers[d % len(layers)]
                        for j, x in enumerate(range(a, b + 1)):
                            if grid[rr][x] != 1:
                                proposals.setdefault((rr, x), []).append(vals[j])
                        d += 1
                        rr += step

            def extend_horizontal(start_col, step, lo, hi):
                if not (0 <= start_col < w):
                    return
                runs = []
                r = lo
                while r <= hi:
                    if grid[r][start_col] not in (1, 8):
                        a = r
                        while r + 1 <= hi and grid[r + 1][start_col] not in (1, 8):
                            r += 1
                        runs.append((a, r))
                    r += 1

                for a, b in runs:
                    layers = [[grid[y][start_col] for y in range(a, b + 1)]]
                    nc = start_col + step
                    if 0 <= nc < w and all(grid[y][nc] not in (1, 8) for y in range(a, b + 1)):
                        layers.append([grid[y][nc] for y in range(a, b + 1)])
                    d = 0
                    cc = start_col
                    while 0 <= cc < w:
                        vals = layers[d % len(layers)]
                        for j, y in enumerate(range(a, b + 1)):
                            if grid[y][cc] != 1:
                                proposals.setdefault((y, cc), []).append(vals[j])
                        d += 1
                        cc += step

            # Only use bands directly adjacent to the component's bounding box.
            extend_vertical(r0 - 1, -1, c0, c1)
            extend_vertical(r1 + 1, 1, c0, c1)
            extend_horizontal(c0 - 1, -1, r0, r1)
            extend_horizontal(c1 + 1, 1, r0, r1)

    for (r, c), vals in proposals.items():
        if grid[r][c] == 8 or len(vals) > 1:
            out[r][c] = vals[-1]
    return out

